package com.mendes.scheduling_platform.booking; import jakarta.persistence.*; import lombok.*; import java.time.*; import java.math.*;
@Entity @Table(name="bookings") @Getter @Setter @NoArgsConstructor public class Booking { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long tenantId; private Long venueId; private Long customerId; private OffsetDateTime startDateTime; private OffsetDateTime endDateTime; @Enumerated(EnumType.STRING) private Status status=Status.PENDING; private BigDecimal totalAmount; @Enumerated(EnumType.STRING) private PaymentStatus paymentStatus=PaymentStatus.PENDING; private Instant createdAt=Instant.now(); public enum Status { PENDING, CONFIRMED, CANCELLED, COMPLETED } public enum PaymentStatus { PENDING, PAID, REFUNDED } }
